using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RentalCamera.Data;
namespace RentalCamera.Controllers; public class GiaThueController:BaseController{private readonly RentalCameraDbContext _db;public GiaThueController(RentalCameraDbContext db)=>_db=db;public async Task<IActionResult> Index()=>View(await _db.DongMay.Include(x=>x.ThuongHieu).OrderBy(x=>x.TenDongMay).ToListAsync());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Update(string id,decimal giaThueNgay,decimal tienCoc,decimal phanTramGiamGia){var x=await _db.DongMay.FindAsync(id);if(x==null)return NotFound();if(giaThueNgay<0||tienCoc<0||phanTramGiamGia<0||phanTramGiamGia>100){TempData["Error"]="Giá trị giá thuê, tiền cọc hoặc giảm giá không hợp lệ.";return RedirectToAction("Index");}x.GiaThueNgay=giaThueNgay;x.TienCoc=tienCoc;x.PhanTramGiamGia=phanTramGiamGia;await _db.SaveChangesAsync();TempData["Ok"]="Đã cập nhật chính sách giá.";return RedirectToAction("Index");}}
